import 'package:flutter/material.dart';
import 'package:intl/intl.dart';
import '../services/cloud_config.dart';

class CloudOrdersScreen extends StatefulWidget { const CloudOrdersScreen({super.key}); @override State<CloudOrdersScreen> createState()=>_CloudOrdersScreenState(); }
class _CloudOrdersScreenState extends State<CloudOrdersScreen> {
 bool loading=true; String? error; List<Map<String,dynamic>> orders=[]; final money=NumberFormat('#,##0.##','en');
 @override void initState(){super.initState();load();}
 Future<void> load() async {setState(()=>{loading=true,error=null});try{final rows=await CloudConfig.client.from('customer_orders').select('id,order_code,customer_name,customer_phone,pickup_at,notes,status,total,created_at,customer_order_items(fish_name,quantity_kg,line_total)').order('created_at',ascending:false);if(!mounted)return;setState(()=>orders=List<Map<String,dynamic>>.from(rows));}catch(_){if(!mounted)return;setState(()=>error='تعذر تحميل الطلبات. تحقق من قاعدة البيانات وصلاحية المدير.');}finally{if(mounted)setState(()=>loading=false);}}
 Future<void> changeStatus(String id,String status) async {try{await CloudConfig.client.from('customer_orders').update({'status':status}).eq('id',id);await load();}catch(_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تعذر تحديث حالة الطلب. تحقق من صلاحيات المدير.')));}}
 String date(dynamic value){final d=DateTime.tryParse(value?.toString()??'');return d==null?'غير محدد':DateFormat('yyyy/MM/dd - hh:mm a').format(d.toLocal());}
 Widget line(String label,dynamic value)=>Padding(padding:const EdgeInsets.symmetric(vertical:4),child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[SizedBox(width:112,child:Text(label+':',style:const TextStyle(color:Colors.black54))),Expanded(child:Text(value?.toString()??'—'))]));
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('حجوزات المتجر الإلكتروني'),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh))]),body:loading?const Center(child:CircularProgressIndicator()):error!=null?Center(child:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,children:[Text(error!,textAlign:TextAlign.center),const SizedBox(height:12),FilledButton(onPressed:load,child:const Text('إعادة المحاولة'))]))):orders.isEmpty?const Center(child:Text('لا توجد حجوزات من المتجر حتى الآن')):RefreshIndicator(onRefresh:load,child:ListView.builder(padding:const EdgeInsets.all(12),itemCount:orders.length,itemBuilder:(context,index){final o=orders[index];final items=List<Map<String,dynamic>>.from(o['customer_order_items']??const []);final status=o['status'] as String???'جديد';const statuses=['جديد','مؤكد','قيد التجهيز','جاهز للاستلام','تم التسليم','ملغي'];return Card(margin:const EdgeInsets.only(bottom:10),child:ExpansionTile(initiallyExpanded:index==0,title:Text((o['customer_name']??'') .toString()+' • '+money((o['total'] as num?)?.toDouble()??0)+' ر.ي',style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text('طلب '+(o['order_code']??'').toString()+' • '+status),childrenPadding:const EdgeInsets.fromLTRB(16,0,16,16),children:[line('الهاتف',o['customer_phone']),line('موعد الاستلام',date(o['pickup_at'])),line('تاريخ الطلب',date(o['created_at'])),if((o['notes'] as String???'').isNotEmpty)line('ملاحظات',o['notes']),const Divider(),const Align(alignment:Alignment.centerRight,child:Text('الأصناف',style:TextStyle(fontWeight:FontWeight.bold))),...items.map((it)=>line((it['fish_name']??'').toString()+' • '+(it['quantity_kg']??'').toString()+' كجم',money((it['line_total'] as num?)?.toDouble()??0)+' ر.ي')),const SizedBox(height:10),DropdownButtonFormField<String>(value:statuses.contains(status)?status:'جديد',decoration:const InputDecoration(labelText:'تحديث حالة الطلب',border:OutlineInputBorder()),items:statuses.map((s)=>DropdownMenuItem(value:s,child:Text(s))).toList(),onChanged:(v){if(v!=null&&v!=status)changeStatus(o['id'].toString(),v);})]));}))); }
}
